import 'package:device_safety_info/device_safety_info.dart';

Future<void> checkSecurity() async {
  final isRooted = await DeviceSafetyInfo.isRooted();
  final isEmulator = await DeviceSafetyInfo.isEmulator();
  final isDebugger = await DeviceSafetyInfo.isDebuggerAttached;
  print('Rooted: $isRooted, Emulator: $isEmulator, Debugger: $isDebugger');
}
